values
  ('seatedcalf', 'Seated calf raise', 'lower', 'Legs', 'Machine', 'weight', array['Calves'], 10, 15, 2.5, 2.5, array['Sit in the machine and place the balls of your feet on the pad.', 'Set the pad on your thighs, just above the knees.', 'Adjust the seat so your knees sit comfortably under the pad.'], array['Push up through the balls of your feet.', 'Pause for a second at the top.', 'Lower slowly until your heels stretch down.'], array['Bouncing at the bottom of the move.', 'Rushing the reps instead of going slow.', 'Going too fast and skipping the stretch at the bottom.'], '', 'Standing calf raise', 60),
  ('inclinelegraise', 'Incline bench leg raise', 'lower', 'Core', 'Bench', 'bodyweight', array['Abs', 'Core'], 8, 15, 2.5, 2.5, array['Lie on an incline bench and hold the sides or the top edge.', 'Keep your legs straight and together in front of you.', 'Brace your belly before you start the first rep.'], array['Lift your legs up until your hips start to tilt.', 'Lower slowly without letting your feet touch the floor.', 'Breathe out as you lift and in as you lower.'], array['Swinging your legs instead of using your belly.', 'Letting your lower back arch off the bench.', 'Bending your knees a lot to make it easier.'], '', 'Lying leg raise', 61),
  ('verticalraise', 'Vertical leg raise machine', 'lower', 'Core', 'Machine', 'bodyweight', array['Abs', 'Core'], 8, 15, 2.5, 2.5, array['Stand in the machine and grip the handles firmly.', 'Rest your forearms on the pads and lean back.', 'Let your legs hang straight down in front of you.'], array['Tighten your belly and lift your knees toward your chest.', 'Pause briefly at the top of the lift.', 'Lower your legs slowly under control.'], array['Using momentum to swing your legs up.', 'Leaning forward and pulling with your arms.', 'Dropping your legs fast at the bottom.'], '', 'Captain''s chair leg raise', 62),
  ('abroller', 'Ab roller', 'lower', 'Core', 'Bodyweight', 'bodyweight', array['Abs', 'Core'], 8, 15, 2.5, 2.5, array['Kneel on a mat and hold the roller with both hands.', 'Keep your hands shoulder-width apart on the handle.', 'Keep your back straight and your hips in line.'], array['Roll forward slowly, keeping your belly tight.', 'Go only as far as you can keep your back flat.', 'Pull back using your belly, not your hips.'], array['Letting your lower back sag toward the floor.', 'Rolling out too far and losing control.', 'Holding your breath during the whole set.'], '', 'Plank', 63),
  ('tbarrow', 'T-bar row', 'upper', 'Back', 'Machine', 'weight', array['Lats', 'Mid back'], 8, 12, 2.5, 2.5, array['Stand over the T-bar with feet set wide and knees soft.', 'Grip the handle with both hands and keep your back flat.', 'Hinge forward at the hips until your torso is near level.'], array['Pull the handle toward your lower chest.', 'Squeeze your shoulder blades together at the top.', 'Lower the weight slowly until your arms are straight.'], array['Rounding your back to lift the weight.', 'Using jerky swings to start each rep.', 'Shrugging your shoulders up toward your ears.'], '', 'Seated cable row', 64),
  ('barbellbench', 'Barbell bench press', 'upper', 'Chest', 'Barbell', 'weight', array['Chest', 'Triceps', 'Front shoulders'], 6, 10, 2.5, 2.5, array['Lie on a flat bench with your eyes under the bar.', 'Grip the bar a bit wider than your shoulders.', 'Plant your feet firmly and keep your back on the bench.'], array['Lower the bar slowly to your mid chest.', 'Press the bar up in a smooth line.', 'Keep your wrists straight above your elbows.'], array['Bouncing the bar off your chest.', 'Lifting your hips off the bench to push.', 'Letting your elbows flare out wide.'], '', 'Dumbbell bench press', 65),
  ('barbellsquat', 'Barbell back squat', 'lower', 'Legs', 'Barbell', 'weight', array['Quads', 'Glutes', 'Hamstrings'], 6, 10, 2.5, 5, array['Set the bar on your upper back, across the shoulders.', 'Stand with feet about shoulder-width apart, toes slightly out.', 'Brace your core before you unrack the bar.'], array['Sit back and down until your thighs are near parallel.', 'Keep your chest up and your back straight.', 'Push through your whole foot to stand up.'], array['Letting your knees cave inward as you stand.', 'Rounding your lower back at the bottom.', 'Lifting your heels off the floor.'], '', 'Goblet squat', 66),
  ('deadlift', 'Conventional deadlift', 'upper', 'Back', 'Barbell', 'weight', array['Lower back', 'Glutes', 'Hamstrings'], 5, 8, 2.5, 2.5, array['Stand with the bar over the middle of your feet.', 'Bend down and grip the bar just outside your legs.', 'Set your back flat and your chest up before you lift.'], array['Push the floor away with your legs as the bar rises.', 'Keep the bar close to your shins the whole way.', 'Stand tall and squeeze your glutes at the top.'], array['Rounding your back as you pull the bar up.', 'Jerking the bar off the floor instead of pulling smoothly.', 'Leaning back at the top instead of standing tall.'], '', 'Romanian deadlift', 67),
  ('ohpress', 'Barbell overhead press', 'upper', 'Shoulders', 'Barbell', 'weight', array['Front shoulders', 'Side shoulders', 'Triceps'], 6, 10, 2.5, 2.5, array['Set the bar on the rack at about collarbone height.', 'Grip the bar slightly wider than shoulder-width.', 'Stand tall with feet apart and your core braced.'], array['Press the bar straight up past your face.', 'Move your head back, then tuck it under the bar at the top.', 'Lower the bar slowly back to your collarbones.'], array['Arching your lower back to push the bar up.', 'Pressing the bar in front of your face.', 'Bending your knees to help push the weight.'], '', 'Dumbbell shoulder press', 68),
  ('pullup', 'Pull-up', 'upper', 'Back', 'Bodyweight', 'bodyweight', array['Lats', 'Biceps', 'Upper back'], 8, 15, 2.5, 2.5, array['Grip the bar a bit wider than your shoulders, palms facing away.', 'Hang with arms straight and your feet off the floor.', 'Brace your core and keep your legs together.'], array['Pull your chest up toward the bar.', 'Lead with your elbows and drive them down.', 'Lower yourself slowly until your arms are straight.'], array['Kicking your legs to swing up.', 'Stopping halfway without reaching the top.', 'Dropping down fast at the bottom.'], '', 'Lat pulldown', 69),
  ('chinup', 'Chin-up', 'upper', 'Back', 'Bodyweight', 'bodyweight', array['Biceps', 'Lats', 'Upper back'], 8, 15, 2.5, 2.5, array['Grip the bar with palms facing you, shoulder-width apart.', 'Hang with your arms fully straight and feet off the floor.', 'Brace your core and keep your body steady.'], array['Pull your chest toward the bar, elbows pointing down.', 'Squeeze your back at the top of the move.', 'Lower yourself slowly until your arms are straight.'], array['Swinging your body to get your chin up.', 'Only going halfway up each rep.', 'Letting go and dropping at the bottom.'], '', 'Assisted pull-up', 70),
  ('dips', 'Parallel bar dips', 'upper', 'Chest', 'Bodyweight', 'bodyweight', array['Triceps', 'Chest', 'Front shoulders'], 8, 15, 2.5, 2.5, array['Grip the parallel bars and lift yourself up with arms straight.', 'Keep your body upright with your legs bent behind you.', 'Hold your shoulders down and away from your ears.'], array['Lower yourself until your elbows reach about 90 degrees.', 'Push back up until your arms are straight.', 'Keep your elbows pointing back, not flared out wide.'], array['Going down too far and straining your shoulders.', 'Swinging your legs to push yourself up.', 'Shrugging your shoulders up toward your ears.'], '', 'Bench dips', 71),
  ('bbrow', 'Barbell bent-over row', 'upper', 'Back', 'Barbell', 'weight', array['Lats', 'Mid back', 'Biceps'], 6, 10, 2.5, 2.5, array['Stand with feet hip-width apart and the bar in front of your shins.', 'Hinge forward at the hips until your torso is near level.', 'Grip the bar just outside your knees, arms straight.'], array['Pull the bar toward your lower ribs.', 'Squeeze your shoulder blades together at the top.', 'Lower the bar slowly until your arms are straight.'], array['Rounding your back during each rep.', 'Standing up as you pull, using body swing.', 'Pulling the bar up toward your neck instead of your belly.'], '', 'Dumbbell row', 72),
  ('bbhipthrust', 'Barbell hip thrust', 'lower', 'Legs', 'Barbell', 'weight', array['Glutes', 'Hamstrings'], 8, 12, 2.5, 5, array['Sit on the floor with your upper back against a bench.', 'Roll the bar over your hips, with a pad on it.', 'Plant your feet flat and hip-width apart.'], array['Drive through your heels and lift your hips up.', 'Squeeze your glutes hard at the top.', 'Lower your hips slowly back toward the floor.'], array['Arching your lower back at the top of the move.', 'Pushing through your toes instead of your heels.', 'Letting the bar roll off your hips.'], '', 'Glute bridge', 73),
  ('bulgarian', 'Bulgarian split squat', 'lower', 'Legs', 'Dumbbells', 'weight', array['Quads', 'Glutes'], 8, 12, 2, 2, array['Stand a stride in front of a bench with dumbbells at your sides.', 'Rest the top of one foot on the bench behind you.', 'Keep your front foot flat and your torso upright.'], array['Lower your back knee toward the floor slowly.', 'Push through your front heel to stand back up.', 'Keep your front knee in line with your toes.'], array['Standing too close to the bench, so the knee bends too far.', 'Leaning forward too much and losing balance.', 'Pushing off the back foot instead of the front leg.'], '', 'Dumbbell lunge', 74),
  ('seatedlegcurl', 'Seated leg curl', 'lower', 'Legs', 'Machine', 'weight', array['Hamstrings'], 10, 15, 2.5, 2.5, array['Sit in the machine and adjust the seat so the pivot lines up with your knees.', 'Place the pad just above your ankles.', 'Hold the handles and keep your back against the seat.'], array['Curl the pad down toward your hips.', 'Squeeze your hamstrings at the bottom.', 'Return the weight slowly to the start.'], array['Lifting your hips off the seat to help.', 'Letting the weight slam back down.', 'Setting the pad too high on your legs.'], '', 'Lying leg curl', 75),
  ('shrug', 'Dumbbell shrug', 'upper', 'Shoulders', 'Dumbbells', 'weight', array['Traps'], 8, 12, 2, 2, array['Stand tall holding a dumbbell in each hand at your sides.', 'Keep your arms straight and your palms facing your legs.', 'Stand with feet hip-width apart and your chest up.'], array['Lift your shoulders straight up toward your ears.', 'Pause for a second at the top.', 'Lower the weights slowly back down.'], array['Rolling your shoulders in circles.', 'Bending your elbows to lift the weight.', 'Using too much weight and rocking your body.'], '', 'Barbell shrug', 76),
  ('skullcrusher', 'Lying triceps extension', 'upper', 'Arms', 'Barbell', 'weight', array['Triceps'], 8, 12, 2.5, 2.5, array['Lie on a flat bench holding a bar with arms straight above you.', 'Grip the bar about shoulder-width apart.', 'Keep your upper arms still and pointing up.'], array['Bend your elbows to lower the bar toward your forehead.', 'Keep your elbows pointing up and steady.', 'Straighten your arms to press the bar back up.'], array['Letting your elbows flare out wide.', 'Lowering the bar too fast and losing control.', 'Moving your shoulders instead of just your elbows.'], '', 'Triceps pushdown', 77),
  ('ezcurl', 'EZ-bar curl', 'upper', 'Arms', 'Barbell', 'weight', array['Biceps', 'Forearms'], 8, 12, 2.5, 2.5, array['Stand tall holding the EZ-bar at the angled grips.', 'Keep your elbows close to your sides.', 'Let the bar hang at arm''s length in front of you.'], array['Curl the bar up toward your shoulders.', 'Keep your upper arms still throughout the move.', 'Lower the bar slowly until your arms are straight.'], array['Swinging your body to lift the bar.', 'Letting your elbows drift forward.', 'Dropping the bar fast at the bottom.'], '', 'Barbell curl', 78),
  ('concentration', 'Concentration curl', 'upper', 'Arms', 'Dumbbells', 'weight', array['Biceps'], 8, 12, 2, 2, array['Sit on a bench with your legs apart.', 'Hold a dumbbell in one hand between your knees.', 'Rest your upper arm on the inside of your thigh.'], array['Curl the dumbbell up toward your shoulder.', 'Squeeze your bicep at the top.', 'Lower the weight slowly until your arm is straight.'], array['Lifting your elbow off your thigh.', 'Leaning your body to swing the weight up.', 'Rushing the lowering part of the move.'], '', 'Dumbbell curl', 79),
  ('crunchmachine', 'Ab crunch machine', 'lower', 'Core', 'Machine', 'weight', array['Abs'], 10, 15, 2.5, 2.5, array['Sit on the seat and grip the handles.', 'Adjust the seat so the pad sits against your chest.', 'Keep your feet flat and your back against the pad.'], array['Crunch your chest down toward your hips.', 'Keep your hips still and only your upper back moves.', 'Return slowly to the start without losing tension.'], array['Pulling with your arms instead of your belly.', 'Going too heavy and rocking your body.', 'Holding your breath for the whole set.'], '', 'Cable crunch', 80),
  ('russiantwist', 'Russian twist', 'lower', 'Core', 'Bodyweight', 'bodyweight', array['Obliques', 'Abs'], 8, 15, 2.5, 2.5, array['Sit on the floor with knees bent and feet lifted slightly.', 'Lean back until your torso forms a V shape with your thighs.', 'Clasp your hands together in front of your chest.'], array['Rotate your upper body to one side, then the other.', 'Keep your back straight and your belly tight.', 'Move slowly and touch the floor beside your hips.'], array['Rounding your back as you twist.', 'Moving only your arms instead of your torso.', 'Rushing the reps without control.'], '', 'Side plank', 81),
  ('bicyclecrunch', 'Bicycle crunch', 'lower', 'Core', 'Bodyweight', 'bodyweight', array['Abs', 'Obliques'], 8, 15, 2.5, 2.5, array['Lie on your back with hands lightly behind your head.', 'Lift your shoulders off the floor slightly.', 'Lift your knees to a table-top position.'], array['Bring one elbow toward the opposite knee.', 'Straighten the other leg as you switch sides.', 'Move at a steady pace without pulling on your neck.'], array['Pulling your neck forward with your hands.', 'Moving too fast to control the twist.', 'Letting your lower back lift off the floor.'], '', 'Crunch', 82),
  ('woodchop', 'Cable woodchop', 'lower', 'Core', 'Cable', 'weight', array['Obliques', 'Abs'], 8, 12, 2.5, 2.5, array['Set the cable pulley high and stand side-on to the machine.', 'Hold the handle with both hands and step away to add tension.', 'Keep your feet wide and your knees slightly bent.'], array['Pull the handle down across your body toward the opposite hip.', 'Turn your torso as you move through the twist.', 'Return slowly to the starting position with control.'], array['Using your arms only and not turning your body.', 'Keeping your knees locked and stiff.', 'Using too much weight and losing balance.'], '', 'Pallof press', 83),
