  ('dbfly', 'Dumbbell fly', 'upper', 'Chest', 'Dumbbells', 'weight', array['Chest', 'Front shoulders'], 10, 15, 2, 2, array['Lie on a flat bench holding a dumbbell in each hand above your chest.', 'Keep your palms facing each other.', 'Keep a soft bend in your elbows throughout.'], array['Open your arms out to the sides in a wide arc.', 'Feel a stretch across your chest at the bottom.', 'Bring the weights back up over your chest.'], array['Bending your elbows into a press.', 'Lowering the weights too far and straining the shoulders.', 'Bouncing the weights at the bottom.'], '', 'Cable fly', 85),
  ('wristcurl', 'Wrist curl', 'upper', 'Arms', 'Dumbbells', 'weight', array['Forearms'], 10, 15, 2, 2, array['Sit on a bench with your forearms resting on your thighs.', 'Let your wrists hang over the edge of your knees.', 'Hold a light dumbbell in each hand with palms up.'], array['Curl your wrists up as far as you can.', 'Lower the weights slowly down into a stretch.', 'Move only your wrists, keeping your forearms still.'], array['Using too much weight and moving your whole arm.', 'Rushing the lowering part.', 'Letting your forearms lift off your thighs.'], '', 'Reverse wrist curl', 86),
  ('stepup', 'Dumbbell step-up', 'lower', 'Legs', 'Dumbbells', 'weight', array['Quads', 'Glutes'], 8, 12, 2, 2, array['Hold a dumbbell in each hand and stand facing a bench or step.', 'Place one whole foot flat on the bench.', 'Stand tall with your chest up.'], array['Push through your front heel to stand up on the bench.', 'Step down slowly with control.', 'Keep your front knee in line with your toes.'], array['Pushing off the floor with your back foot.', 'Using a bench that is too high.', 'Letting your front knee cave inward.'], '', 'Bodyweight step-up', 87),
  ('hanglegraise', 'Hanging leg raise', 'lower', 'Core', 'Bodyweight', 'bodyweight', array['Abs', 'Core'], 8, 15, 2.5, 2.5, array['Hang from a pull-up bar with your hands shoulder-width apart.', 'Keep your legs straight and together.', 'Brace your belly before you lift.'], array['Lift your legs up toward the bar using your belly.', 'Pause briefly at the top of the lift.', 'Lower your legs slowly without swinging.'], array['Swinging your legs to build momentum.', 'Bending your knees a lot to make it easier.', 'Lowering your legs fast and losing control.'], '', 'Hanging knee raise', 88),
  ('declinesitup', 'Decline sit-up', 'lower', 'Core', 'Bench', 'bodyweight', array['Abs', 'Core'], 8, 15, 2.5, 2.5, array['Lock your feet under the pads of a decline bench.', 'Lie back with your head lower than your feet.', 'Cross your arms over your chest or hold a light weight.'], array['Curl your upper body up toward your knees.', 'Breathe out as you come up.', 'Lower slowly until your back touches the bench.'], array['Pulling on your neck with your hands.', 'Using momentum to swing up.', 'Letting your feet slip from the pads.'], '', 'Sit-up', 89),
  ('inclinebb', 'Incline barbell press', 'upper', 'Chest', 'Barbell', 'weight', array['Upper chest', 'Front shoulders', 'Triceps'], 6, 10, 2.5, 2.5, array['Set the bench to a low incline and lie back with eyes under the bar.', 'Grip the bar a bit wider than your shoulders.', 'Plant your feet firmly and keep your back flat on the bench.'], array['Lower the bar slowly to your upper chest.', 'Press the bar up in a straight line.', 'Keep your elbows at a comfortable angle, not flared out.'], array['Setting the bench too steep, so it becomes a shoulder press.', 'Bouncing the bar off your chest.', 'Lifting your hips off the bench.'], '', 'Incline dumbbell press', 90),
